import itertools
import random
import json
from problems import ThreeColoring, ThreeSat
from reduce import reduce


def solve_three_coloring(instance):
    n = instance['n']
    edges = [tuple(e) for e in instance['edges']]
    # try all colorings with colors 0,1,2
    for coloring in itertools.product(range(3), repeat=n):
        ok = True
        for u, v in edges:
            if coloring[u] == coloring[v]:
                ok = False
                break
        if ok:
            return True
    return False


def solve_three_sat(instance):
    m = instance['num_vars']
    clauses = [tuple(c) for c in instance['clauses']]
    for assignment in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            # clause has three literals
            sat = False
            for lit in clause:
                var = abs(lit) - 1
                val = assignment[var]
                if lit > 0:
                    sat = sat or val
                else:
                    sat = sat or (not val)
                if sat:
                    break
            if not sat:
                ok = False
                break
        if ok:
            return True
    return False


def random_graph(n, p=0.5):
    edges = []
    for u in range(n):
        for v in range(u+1, n):
            if random.random() < p:
                edges.append([u, v])
    return {"n": n, "edges": edges}

def test_all_small_graphs(max_n=4):
    total = 0
    passed = 0
    for n in range(max_n+1):
        # generate all possible edge sets
        vertices = list(range(n))
        all_pairs = [(u, v) for u in vertices for v in vertices if u < v]
        for mask in range(1 << len(all_pairs)):
            edges = []
            for i, (u, v) in enumerate(all_pairs):
                if mask & (1 << i):
                    edges.append([u, v])
            instance = {"n": n, "edges": edges}
            ThreeColoring.validate(instance)
            red = reduce(instance)
            ThreeSat.validate(red)
            ans1 = solve_three_coloring(instance)
            ans2 = solve_three_sat(red)
            total += 1
            if ans1 == ans2:
                passed += 1
            else:
                print("Mismatch!", instance, red, ans1, ans2)
                return False, total, passed
    return True, total, passed

if __name__ == "__main__":
    ok, total, passed = test_all_small_graphs(4)
    print("All tests passed?", ok, "tested", total, "instances, passed", passed)
    # also random tests up to n=6
    for _ in range(100):
        n = random.randint(0,6)
        inst = random_graph(n, 0.4)
        ThreeColoring.validate(inst)
        red = reduce(inst)
        ThreeSat.validate(red)
        assert solve_three_coloring(inst) == solve_three_sat(red)
    print("Random tests passed")
EOF"}

